-- MyNclex bank gap-fill batch: gap-11 — Mental Health, psychosis, altered
-- perception and therapeutic response.
-- Batch id: gapfill-20260728
-- Item id block: 550001–550999 (35 items used: 550001–550035)
-- Type mix: 16 MCQ, 9 SATA, 3 SELECT_N, 3 MATRIX, 2 MATRIX_MR, 1 CLOZE, 1 TF
-- Focus: delusion vs hallucination vs illusion; the three-way response rule
-- (functional psychosis / dementia / delirium); delirium vs dementia vs
-- depression; disordered thought and speech; positive vs negative symptoms;
-- therapeutic communication and boundaries; milieu, restraint and de-escalation;
-- suicide and aggression risk assessment.

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_550001', 'MCQ',
 'During an evening shift on a mental health unit, a client points at a dressing gown hanging on the back of the door and says that a man is standing in the corner watching her. When the nurse switches on the light, the client looks again and says it is only her dressing gown. Which term describes what the client experienced?',
 'An illusion is a misinterpretation of a stimulus that is genuinely present, so the referent is real and the perception corrects itself once the stimulus is clarified. A hallucination has no external stimulus at all, and a delusion is a belief rather than a perception and does not yield to evidence. Distinguishing the three matters because the nursing response differs: an illusion is best treated by altering the environment, not by reality testing or by exploring content.',
 '{"options":[{"id":"A","text":"Delusion"},{"id":"B","text":"Hallucination"},{"id":"C","text":"Illusion"},{"id":"D","text":"Confabulation"}]}'::jsonb,
 '{"answer":"C","feedback":{"A":"Incorrect. A delusion is a fixed false belief that persists despite contrary evidence, whereas this client accepted the correction at once.","B":"Incorrect. A hallucination occurs with no external stimulus, but a real dressing gown was hanging on the door.","C":"Correct. An illusion is a misinterpretation of a real external stimulus and resolves when the stimulus is made clear.","D":"Incorrect. Confabulation is the filling of a memory gap with invented detail, not the misreading of an object that is present."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Altered perception', 'Illusion', 'Very easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550002', 'MCQ',
 'A client with schizophrenia tells the nurse during a morning ward round that the government has placed his name on a secret list and that the staff have been paid to report on him. He has held this belief for several months and it does not change when he is shown his admission paperwork. Which term best describes this finding?',
 'A delusion is a fixed false belief held with conviction despite clear contrary evidence, and its subtype is named for its theme. A persecutory delusion is the belief that one is being watched, plotted against or harmed by others, and it is the commonest subtype in schizophrenia. Naming the subtype matters because persecutory content raises the likelihood that the client will refuse food, medication or care he believes is part of the plot.',
 '{"options":[{"id":"A","text":"Persecutory delusion"},{"id":"B","text":"Auditory hallucination"},{"id":"C","text":"Illusion"},{"id":"D","text":"Grandiose delusion"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. The theme is of being watched, listed and plotted against, which is the persecutory subtype of delusion.","B":"Incorrect. Nothing in the report describes a sensory experience such as hearing a voice; this is a belief, not a perception.","C":"Incorrect. An illusion is a misperception of a real object, and there is no misread stimulus here.","D":"Incorrect. A grandiose delusion involves inflated worth, power or identity, not the belief that one is being persecuted."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Delusions', 'Persecutory delusion', 'Easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550003', 'MCQ',
 'An older client on a surgical ward becomes frightened during the night and tells the nurse that the intravenous pole beside the bed is a person holding a knife. The pole is casting a long shadow across the wall. Which action by the nurse is BEST?',
 'Because an illusion has a real referent, the most effective intervention changes the stimulus rather than the belief. Improving lighting, removing the shadow and naming the object with the client corrects the perception directly and reduces fear without argument. Reality testing, exploring content or sedation are all aimed at the wrong mechanism and leave the misread stimulus in place.',
 '{"options":[{"id":"A","text":"Switch on the bedside lamp, move the pole clear of the shadow and name the object together with the client"},{"id":"B","text":"Tell the client firmly that nobody is in the room and that this is part of being unwell"},{"id":"C","text":"Give the prescribed as-required sedative before discussing the situation further"},{"id":"D","text":"Explain that the nurse cannot see anyone and leave the room quiet and dark so the client can sleep"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. An illusion is a misread real stimulus, so altering the lighting and identifying the object with the client corrects the perception at source.","B":"Incorrect. Bald contradiction argues with a frightened client and does nothing about the shadow that is producing the fear.","C":"Incorrect. Sedation is not the first response to a correctable environmental misperception and increases the risk of falls and delirium.","D":"Incorrect. Leaving the room dark preserves the very stimulus that is being misinterpreted and abandons a frightened client."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Altered perception', 'Nursing response to an illusion', 'Medium', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550004', 'MCQ',
 'A client admitted with acute mania tells the nurse that he owns the hospital, that the consultant reports to him, and that he is leaving now to address the board of directors. Which response by the nurse is most therapeutic?',
 'The therapeutic response to a delusion in a functional disorder has three parts: acknowledge the feeling behind the belief, state reality once without arguing, then set and enforce a limit. Debating the belief or demanding proof engages the client in a power struggle and tends to entrench the delusion, while exploring its detail rehearses and reinforces it. Acknowledging the feeling keeps the relationship intact so the limit can be enforced without escalation.',
 '{"options":[{"id":"A","text":"You do not own this hospital and you are not permitted to leave the unit."},{"id":"B","text":"I can see you are feeling very powerful today. I do not see it the same way, and you need to stay on the unit until the doctor reviews you."},{"id":"C","text":"If you own the hospital, show me the documents that prove it."},{"id":"D","text":"Tell me more about how you came to own the hospital."}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. Flat contradiction with no acknowledgement of the feeling invites an argument and a power struggle with a manic client.","B":"Correct. It acknowledges the feeling, states the nurse view of reality once without debate, and sets a clear limit.","C":"Incorrect. Demanding proof engages with the delusion on its own terms and tends to strengthen it.","D":"Incorrect. Exploring the content in detail rehearses and reinforces the delusional belief rather than easing the distress behind it."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Delusions', 'Grandiose delusion', 'Medium', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550005', 'MCQ',
 'A client with schizophrenia is sitting rigidly in the day room, appears to be listening to something the nurse cannot hear, and says that the voices are back and are very loud today. Which action should the nurse take FIRST?',
 'The content of an auditory hallucination determines the level of risk, so it must be established before any other decision is made. Command hallucinations directing the client to harm himself or another person change observation level, environment and staffing immediately, and none of that can be judged without knowing what the voice is saying. Asking directly does not reinforce the hallucination; it is the assessment on which every subsequent safety action depends.',
 '{"options":[{"id":"A","text":"Ask the client what the voices are saying to him"},{"id":"B","text":"Reassure the client that the voices are not real and will pass"},{"id":"C","text":"Increase the observation level and inform the nurse in charge"},{"id":"D","text":"Give the prescribed as-required antipsychotic"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. The content of the voice determines whether it is a command to harm, so this assessment must come before any intervention.","B":"Incorrect. Denying the experience is not reassuring to the client and gathers no information about risk.","C":"Incorrect. Raising the observation level is likely to be needed, but the level chosen depends on what the voices are saying.","D":"Incorrect. Medication may help, but giving it before assessing the content leaves the immediate risk unknown."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Hallucinations', 'Command hallucinations', 'Hard', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550006', 'MCQ',
 'A client with schizophrenia has refused all meals for two days, saying that the staff are putting poison in the food. The client is alert, oriented and medically stable. Which response by the nurse is most appropriate?',
 'In psychosis arising from a functional disorder the client can retain a statement of reality, so the nurse acknowledges the feeling, presents reality once without arguing, and then offers a practical way forward. Justifying the safety of the food invites debate, and exploring who is behind the poisoning reinforces the delusional structure. A sealed item the client opens himself respects the fear while keeping nutrition on track.',
 '{"options":[{"id":"A","text":"I can see the food frightens you. It is not poisoned, and I will bring you a sealed carton of juice and an unpeeled orange so you can open them yourself."},{"id":"B","text":"There is no poison in the food. Everyone on the ward eats it and nobody has become ill."},{"id":"C","text":"Who do you believe is putting the poison in your food?"},{"id":"D","text":"If you continue refusing to eat, a nasogastric tube will have to be passed."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. It names the feeling, presents reality once without argument, and offers a practical alternative the client can accept.","B":"Incorrect. Marshalling evidence turns the exchange into a debate the nurse cannot win and tends to harden the belief.","C":"Incorrect. Asking who is responsible explores and elaborates the delusion instead of addressing the fear behind it.","D":"Incorrect. Using a procedure as a threat is coercive, damages trust and is not a therapeutic response to a delusion."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Therapeutic response to psychosis', 'Psychosis in a functional disorder', 'Medium', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550007', 'MCQ',
 'A client with moderate Alzheimer disease on a care-of-the-older-person ward tells the nurse every afternoon that the staff are stealing her clothes and putting poison in her tea. She becomes tearful each time she is told that this is not happening. Which response by the nurse is most appropriate?',
 'Presenting reality only helps when the client can retain the correction. In dementia the short-term memory deficit means the correction is lost within minutes, so the client experiences the distress of being contradicted over and over with no lasting benefit. The evidence-based approach is to acknowledge the feeling and redirect to a calm, familiar activity, which addresses the emotion that is actually driving the accusation.',
 '{"options":[{"id":"A","text":"That sounds upsetting. Come and help me fold this laundry, and I will make you a fresh cup of tea while we do it."},{"id":"B","text":"Nobody is stealing from you. Your clothes are all here in your locker and I will show you now."},{"id":"C","text":"Nobody would poison your tea. Every member of staff here has been checked before being employed."},{"id":"D","text":"Tell me exactly who you think has been taking your clothes so that I can report it."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Acknowledging the feeling and redirecting to a familiar activity works with a client who cannot retain a correction.","B":"Incorrect. Repeated reality presentation is not retained in dementia and simply repeats the distress of being contradicted.","C":"Incorrect. Defending the staff argues with the accusation and misses the fear and loss of control underneath it.","D":"Incorrect. Investigating the accusation as fact elaborates the false belief and delays the comfort the client needs."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Therapeutic response to psychosis', 'Psychosis in dementia', 'Hard', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550008', 'MCQ',
 'A client is two days after a hip hemiarthroplasty and has become acutely confused overnight, having been fully oriented on admission. She grips the arm of the nurse and says that the staff have put poison in the drip and that insects are crawling over the bed. Her temperature is 38.4 °C and her urine is cloudy and offensive. Which response by the nurse is most appropriate?',
 'Delirium is acute, fluctuating and reversible, so the therapeutic response reassures the client that she is safe, names the state as temporary, and moves immediately to identify and treat the underlying cause. Unlike dementia, the client can be steadied by calm reassurance and a familiar presence, and unlike a functional psychosis the belief will resolve when the cause is treated rather than through reality testing alone. Sedation without treating the cause deepens and prolongs the delirium.',
 '{"options":[{"id":"A","text":"You are safe and I am staying with you. The drip is fluid, not poison. This confusion comes with infection and it will settle once we treat it, so I am sending a urine sample now."},{"id":"B","text":"Those insects are not real. You have had an operation and you must try to rest."},{"id":"C","text":"Come and sit in the day room with me and we will look through some photographs together."},{"id":"D","text":"I will ask the doctor to prescribe something to calm you before we do anything else."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. It reassures about safety, explains that the state is temporary, and acts on the likely urinary cause of the delirium.","B":"Incorrect. Flat contradiction offers no reassurance and does nothing about the infection driving the confusion.","C":"Incorrect. Redirection is the approach for dementia; in delirium the priority is reassurance plus treatment of the reversible cause.","D":"Incorrect. Sedating first can worsen and prolong delirium and delays identification of the underlying infection."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Therapeutic response to psychosis', 'Psychosis in delirium', 'Hard', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550009', 'MCQ',
 'A client with advanced dementia puts on her coat at four o''clock every afternoon and tells the healthcare assistant that she must go home because her mother is waiting to give her tea. The mother of the client died forty years ago. The healthcare assistant asks the nurse what she should say. Which instruction by the nurse is most appropriate?',
 'A client with advanced dementia who is living in an earlier period of her life cannot retain the news of a bereavement, so telling her that her mother is dead delivers fresh grief that will be repeated every afternoon. Deliberately lying is also avoided because it damages trust when the story is contradicted by another member of staff. The approach that works is to acknowledge the feeling behind the statement and redirect to a related activity in the present.',
 '{"options":[{"id":"A","text":"Say: Your mother is waiting for you? Tell me about her while we walk down to the kitchen and see whether tea is ready."},{"id":"B","text":"Tell her gently but clearly that her mother died many years ago so that she is not misled."},{"id":"C","text":"Tell her that her mother telephoned to say she cannot come today."},{"id":"D","text":"Say nothing about it and take the coat away so that she settles."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. It joins the feeling the client is expressing and redirects to a present-day activity linked to what she is seeking.","B":"Incorrect. The client cannot retain the information, so the bereavement is experienced afresh each time she is told.","C":"Incorrect. Inventing a message is a deliberate untruth that unravels when another member of staff answers differently.","D":"Incorrect. Removing the coat without acknowledgement is dismissive and is likely to provoke distress and resistance."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Therapeutic response to psychosis', 'Reality orientation versus redirection', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550010', 'MCQ',
 'A healthcare assistant reports that an 82-year-old client admitted three days ago for rehabilitation has become confused since the night shift, is pulling at the bedding and did not recognise her daughter this morning. The client was fully oriented on admission. Which action is the PRIORITY for the nurse?',
 'New confusion of hours to days in an older client is delirium until proved otherwise, and delirium is a medical emergency with a treatable cause. Urinary infection, hypoxia, electrolyte disturbance, medication, pain, retention and withdrawal account for most cases, and identifying the cause is what reverses the state. Labelling the change as dementia or managing it only with environmental measures leaves an untreated physical illness progressing.',
 '{"options":[{"id":"A","text":"Screen for a physical cause, starting with a full set of observations and a urine specimen"},{"id":"B","text":"Record a likely diagnosis of dementia in the nursing notes and request a memory assessment"},{"id":"C","text":"Move the client into a side room to reduce stimulation"},{"id":"D","text":"Ask the family to sit with the client overnight"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Acute confusion in an older client signals delirium, and the priority is to find the reversible physical cause.","B":"Incorrect. Dementia develops over months to years; labelling a sudden change as dementia misses a treatable illness.","C":"Incorrect. Isolation in an unfamiliar side room often worsens delirium and does not address the cause.","D":"Incorrect. Familiar company is helpful support but does not identify or treat the underlying physical problem."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Mental Health', 'Psychiatric/Mental Health',
 'Delirium', 'Reversible causes', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_550011', 'MCQ',
 'A client admitted with bipolar disorder in a manic phase says rapidly: I need my shoes, shoes are for walking, walking to the shop, the shop sells bread, bread and butter, my brother is butter fingers at football. Each idea is loosely connected to the one before it. Which term describes this speech pattern?',
 'Flight of ideas is rapid speech in which each thought is linked to the next by a recognisable, if superficial, association, and it is characteristic of mania. It differs from loose associations, where the links between ideas are not discernible, and from word salad, where words are strung together with no grammar or meaning at all. Naming the pattern accurately guides both documentation and the level of structure the client needs in conversation.',
 '{"options":[{"id":"A","text":"Flight of ideas"},{"id":"B","text":"Word salad"},{"id":"C","text":"Neologism"},{"id":"D","text":"Thought blocking"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Rapid speech in which each idea is linked to the last by a loose but traceable association is flight of ideas.","B":"Incorrect. Word salad is a jumble of words with no grammatical or logical connection at all.","C":"Incorrect. A neologism is a word invented by the client that has meaning only to him.","D":"Incorrect. Thought blocking is a sudden stop in mid-sentence with the thought lost, which is the opposite of this pressured flow."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Disordered thought and speech', 'Flight of ideas', 'Very easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550012', 'MCQ',
 'The brother of a client with schizophrenia tells the community nurse that the client sits in one chair all day, says almost nothing and has stopped washing, and that he is simply lazy and needs to be pushed harder. Which response by the nurse is most appropriate?',
 'Negative symptoms such as blunted affect, poverty of speech, avolition and social withdrawal are losses of normal function caused by the illness, not choices. They are commonly mistaken for laziness or depression by families, respond less well to antipsychotic medication than positive symptoms, and improve slowly with structure, graded activity and psychosocial rehabilitation. Correcting the attribution reduces conflict at home and stops the family setting expectations the client cannot yet meet.',
 '{"options":[{"id":"A","text":"What you are describing sounds like the negative symptoms of the illness rather than laziness. They respond less well to medication and improve slowly with structure and small graded steps."},{"id":"B","text":"You are right that he needs pushing. Set him a full daily timetable and insist that he keeps to every part of it."},{"id":"C","text":"He is almost certainly depressed. I will ask the doctor to start an antidepressant."},{"id":"D","text":"Try not to worry about it. Most people with schizophrenia are completely well again within a year."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. It renames the behaviour accurately as negative symptoms and gives a realistic expectation of how change happens.","B":"Incorrect. A full timetable imposed on a client with avolition sets him up to fail and increases conflict at home.","C":"Incorrect. Negative symptoms overlap with depression but jumping to a medication change bypasses assessment by the team.","D":"Incorrect. This is false reassurance and a guarantee of an outcome the nurse cannot promise."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Schizophrenia', 'Negative symptoms', 'Hard', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550013', 'MCQ',
 'On the day of discharge a client hands the nurse a wrapped box of chocolates and a card, saying that the nurse has been very kind to her. Which response by the nurse is most appropriate?',
 'Accepting a personal gift blurs the professional boundary, shifts the relationship towards a social one and can create a sense of obligation on either side. The response that preserves the boundary also preserves the relationship: it thanks the client warmly, declines the gift clearly, and offers an acceptable alternative such as sharing the card with the whole team. Concealing a gift from colleagues is a marker of a boundary violation rather than a way of avoiding one.',
 '{"options":[{"id":"A","text":"Thank you, that is very kind of you. I am not able to accept a personal gift, but I would love to put the card up so the whole team can read it."},{"id":"B","text":"Thank you very much. I will keep it in my locker so the other staff do not see it."},{"id":"C","text":"I cannot accept that. Please take it back with you."},{"id":"D","text":"I will accept it just this once because you are going home today."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. It acknowledges the feeling behind the gift, declines it clearly, and redirects to something the team can accept.","B":"Incorrect. Needing to hide a gift from colleagues is a sign that the professional boundary is being crossed.","C":"Incorrect. A blunt refusal maintains the boundary but rejects the gratitude the client is trying to express.","D":"Incorrect. Making an exception is still acceptance and sets a precedent that erodes the boundary."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Professional boundaries', 'Gifts', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550014', 'MCQ',
 'A client being treated for depression says to the nurse: My husband drinks every night and I cannot cope any more. Do you think I should leave him? Which response by the nurse is most therapeutic?',
 'Giving advice transfers the decision, and its consequences, from the client to the nurse and undermines the autonomy the client needs to recover. The therapeutic move is to turn the question back so that the client explores her own reasoning, which is also the response that keeps her talking. Referring her elsewhere is not wrong in principle but closes down a conversation she is ready to have now, and asking why demands justification and provokes defensiveness.',
 '{"options":[{"id":"A","text":"You are asking whether to leave. What would leaving mean for you?"},{"id":"B","text":"I think you should leave. Nobody should have to live like that."},{"id":"C","text":"That is really a question for the social worker. I can arrange an appointment for you."},{"id":"D","text":"Why have you stayed with him for so long?"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. It turns the question back to the client and invites her to explore the decision, keeping her talking.","B":"Incorrect. Giving advice removes the decision from the client and makes the nurse responsible for the outcome.","C":"Incorrect. Referring the client elsewhere ends a conversation she is ready to have now; keeping her talking is preferable.","D":"Incorrect. A why question demands justification and typically produces defensiveness rather than reflection."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Therapeutic communication', 'Giving advice', 'Medium', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550015', 'MCQ',
 'A client whose mother died last week says quietly to the nurse: I keep setting a place for her at the table. Which response by the nurse best demonstrates empathy?',
 'Empathy is naming and reflecting the feeling the client is expressing so that the client feels understood; sympathy is the nurse describing her own feelings or experience, which moves the focus away from the client. Claiming to know exactly how someone feels is also inaccurate, since no two losses are the same, and it usually shifts the conversation to the nurse. Minimising the loss or offering a silver lining closes the exchange down altogether.',
 '{"options":[{"id":"A","text":"It sounds as though part of you is still expecting her to walk in, and that is painful."},{"id":"B","text":"I know exactly how you feel. I lost my own mother last year and it was terrible."},{"id":"C","text":"You must try not to dwell on it. It does get easier with time."},{"id":"D","text":"At least she did not suffer for very long."}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. It names the feeling the client is expressing and invites her to say more, which is empathy.","B":"Incorrect. This is sympathy combined with self-disclosure and moves the focus from the client to the nurse.","C":"Incorrect. Telling the client not to dwell on the loss minimises it and offers false reassurance.","D":"Incorrect. Looking for a positive in a bereavement minimises the loss and tends to close the conversation."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Therapeutic communication', 'Empathy versus sympathy', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MCQ_550016', 'MCQ',
 'A client admitted eight days ago with severe depression and thoughts of ending his life has been withdrawn and has spent most of the time in bed. This morning he is washed and dressed, has eaten a full breakfast, is smiling, and has given his favourite watch to another client. Which action is the PRIORITY for the nurse?',
 'The period in which energy and motivation return, usually one to two weeks into treatment, is the highest-risk window for suicide, because the client regains the capacity to act before the hopelessness has lifted. A sudden calm or brightening after days of profound withdrawal, especially combined with giving away possessions, is a recognised warning sign rather than evidence of recovery. The response is to raise observation and ask directly about intent, not to relax supervision.',
 '{"options":[{"id":"A","text":"Raise the observation level and ask the client directly about current suicidal thoughts, plan and intent"},{"id":"B","text":"Record the improvement in mood and encourage the client to join the morning group"},{"id":"C","text":"Ask the client to collect the watch back from the other client"},{"id":"D","text":"Contact the doctor to discuss stepping down the level of observation"}]}'::jsonb,
 '{"answer":"A","feedback":{"A":"Correct. Returning energy plus giving away a valued possession suggests a decision has been made, so observation and direct questioning come first.","B":"Incorrect. Documenting the change as improvement misreads a recognised warning sign and leaves the client unprotected.","C":"Incorrect. Retrieving the watch deals with the object rather than the intent it may signal.","D":"Incorrect. Reducing observation during the period of returning energy removes protection at the point of highest risk."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Suicide risk', 'Period of improving energy', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550017', 'SATA',
 'The nurse reviews statements recorded from several clients on a mental health unit. Which statements describe a hallucination? Select all that apply.',
 'A hallucination is a sensory experience occurring without any external stimulus and may be auditory, visual, tactile, gustatory or olfactory, in roughly that order of frequency. A delusion is a belief rather than a perception, whatever its theme, and an illusion is a misinterpretation of a stimulus that is genuinely present. Sorting a client statement into the right category is what determines whether the nurse alters the environment, presents reality or redirects.',
 '{"options":[{"id":"A","text":"A man speaks to me from inside the ceiling light. There is nobody else in the room."},{"id":"B","text":"My bowels have rotted away and there is nothing left inside me."},{"id":"C","text":"I can feel insects crawling about underneath my skin."},{"id":"D","text":"The newsreader looked into the camera last night and gave me my instructions."},{"id":"E","text":"That coat on the door looked like my father standing there, but when you put the light on I could see it is just a coat."},{"id":"F","text":"There is a smell of burning rubber in this room that nobody else can smell."}]}'::jsonb,
 '{"answers":["A","C","F"],"feedback":{"A":"Correct. Hearing a voice when no one is present is an auditory hallucination, the commonest modality.","B":"Incorrect. This is a somatic delusion, a fixed false belief about the body rather than a sensory perception.","C":"Correct. Feeling insects on or under the skin with no stimulus present is a tactile hallucination.","D":"Incorrect. This is an idea of reference, a referential delusion in which neutral events are believed to carry personal messages.","E":"Incorrect. A coat mistaken for a person is an illusion, because a real object was misinterpreted and the perception corrected.","F":"Correct. Smelling something that is not there and that others cannot detect is an olfactory hallucination."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Altered perception', 'Hallucination versus delusion versus illusion', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550018', 'SATA',
 'A client with schizophrenia tells the nurse that a voice is instructing him to hurt the client in the next bed. Which nursing actions are appropriate? Select all that apply.',
 'A command hallucination directed at another person is an immediate safety issue, and the nurse must establish whether the client intends to obey the voice, alert the team, and make the environment safe. Raising observation to the agreed level and separating the person named in the command are protective, not punitive. Denying the voice or leaving the client unobserved in a quiet room removes both the therapeutic contact and the supervision at the moment they are most needed.',
 '{"options":[{"id":"A","text":"Ask the client whether he intends to act on what the voice is telling him"},{"id":"B","text":"Inform the nurse in charge and the multidisciplinary team without delay"},{"id":"C","text":"Place the client on the agreed increased level of observation"},{"id":"D","text":"Tell the client the voice is not real and that he should simply ignore it"},{"id":"E","text":"Move the other client and remove objects that could be used as a weapon from the immediate area"},{"id":"F","text":"Leave the client alone in a quiet room so that the voice has a chance to settle"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Intent to act is the single most important piece of information and must be asked about directly.","B":"Correct. A command to harm another person is escalated to the team immediately so that risk can be managed collectively.","C":"Correct. Increased observation is the standard protective response to a command hallucination directed at another person.","D":"Incorrect. Denying the experience is not reassuring, damages trust and does nothing to reduce the risk.","E":"Correct. Separating the person named and removing potential weapons reduces opportunity while the risk is assessed.","F":"Incorrect. Leaving the client unobserved removes supervision at the point of greatest risk and often intensifies the voices."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Hallucinations', 'Risk to others from command hallucinations', 'Hard', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550019', 'SATA',
 'An older client is admitted from home with confusion, and the family are unsure how long it has been present. Which findings suggest delirium rather than dementia? Select all that apply.',
 'Delirium is distinguished from dementia chiefly by onset, course and attention: it begins over hours to days, fluctuates through the day and is worse at night, and attention is impaired so that the client cannot hold a thread of conversation. Consciousness is clouded and perceptual disturbance, particularly visual, is common. Dementia begins insidiously over months to years, follows a slowly progressive course, and leaves alertness intact until very late.',
 '{"options":[{"id":"A","text":"The change began within the past 24 hours"},{"id":"B","text":"Attention drifts within a single sentence and varies through the day"},{"id":"C","text":"Memory has declined gradually over the past three years"},{"id":"D","text":"The client describes seeing animals moving around the room"},{"id":"E","text":"The client is drowsy by day and agitated and wakeful at night"},{"id":"F","text":"Alertness has been consistently normal throughout the illness"}]}'::jsonb,
 '{"answers":["A","B","D","E"],"feedback":{"A":"Correct. Onset over hours to days is the hallmark of delirium; dementia develops over months to years.","B":"Correct. Fluctuating, impaired attention is the defining cognitive feature of delirium.","C":"Incorrect. A slow decline over years describes dementia rather than an acute confusional state.","D":"Correct. Visual hallucinations are far more common in delirium than in the early stages of dementia.","E":"Correct. Reversal of the sleep-wake cycle with night-time worsening is characteristic of delirium.","F":"Incorrect. Consciousness is clouded and fluctuates in delirium; preserved alertness points towards dementia."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Delirium versus dementia', 'Distinguishing features', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550020', 'SATA',
 'A client on a surgical ward develops acute confusion on the second postoperative day. Which reversible causes should the nurse screen for? Select all that apply.',
 'Delirium is a symptom of an underlying physical problem, and the common reversible causes are infection, especially urinary, electrolyte disturbance, hypoxia, medication, pain, urinary retention and withdrawal from alcohol or benzodiazepines. Screening means observations, oxygen saturation, a urine specimen, bloods including sodium, a bladder scan, a pain assessment and a medication review. Age, family history and a stable long-standing sensory impairment increase vulnerability but are not causes that can be treated to reverse the episode.',
 '{"options":[{"id":"A","text":"Urinary tract infection"},{"id":"B","text":"Hyponatraemia"},{"id":"C","text":"Hypoxia"},{"id":"D","text":"Urinary retention with untreated pain"},{"id":"E","text":"A stable long-standing hearing impairment"},{"id":"F","text":"A family history of dementia"},{"id":"G","text":"Being 82 years of age"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Urinary infection is the single commonest reversible trigger of delirium in older inpatients.","B":"Correct. Sodium disturbance is a frequent and readily correctable cause of acute confusion.","C":"Correct. Hypoxia impairs cerebral function quickly and is reversed by oxygen and treatment of the cause.","D":"Correct. A full bladder and unrelieved pain are common, easily missed and immediately treatable causes.","E":"Incorrect. Long-standing hearing loss increases vulnerability to delirium but is not a reversible cause of this episode.","F":"Incorrect. Family history relates to dementia risk and cannot be treated to reverse acute confusion.","G":"Incorrect. Advanced age is a risk factor for delirium, not a cause that can be corrected."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Mental Health', 'Psychiatric/Mental Health',
 'Delirium', 'Screening for underlying causes', 'Easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SATA_550021', 'SATA',
 'A nurse is reviewing recorded interactions with a student nurse on a mental health placement. Which nurse responses should be identified as non-therapeutic? Select all that apply.',
 'Non-therapeutic responses share one feature: they close the conversation down or move it away from the client. False reassurance and guaranteed outcomes remove the client permission to feel unwell, advice transfers the decision to the nurse, and why questions demand justification and provoke defensiveness. Figurative language and idiom are also avoided with a client who takes words literally, because concrete thinking in psychosis turns a casual phrase into a frightening instruction.',
 '{"options":[{"id":"A","text":"I promise you that you will feel completely better before you go home."},{"id":"B","text":"Why did you stop taking your medication?"},{"id":"C","text":"If I were you I would move out of that house."},{"id":"D","text":"Saying hop into bed for me to a client who takes language literally."},{"id":"E","text":"You said you felt empty. Tell me more about what empty feels like."},{"id":"F","text":"I will sit here with you for a while."},{"id":"G","text":"Remaining silent, seated and attentive while the client gathers her thoughts."}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. This guarantees an outcome the nurse cannot control and is false reassurance.","B":"Correct. A why question asks the client to justify herself and typically produces defensiveness rather than reflection.","C":"Correct. Giving advice transfers the decision from the client to the nurse and undermines autonomy.","D":"Correct. Idiom and figurative language are avoided with a client who thinks concretely and may take the phrase literally.","E":"Incorrect. This is restating followed by an open invitation and is therapeutic.","F":"Incorrect. Offering self communicates worth and availability without demanding anything, and is therapeutic.","G":"Incorrect. Purposeful silence gives the client time to think and is a recognised therapeutic technique."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Therapeutic communication', 'Non-therapeutic responses', 'Easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550022', 'SATA',
 'A newly qualified nurse asks what is meant by milieu therapy on an inpatient mental health unit. Which features should the nurse include in the explanation? Select all that apply.',
 'Milieu therapy treats the physical and social environment of the unit as an active part of treatment rather than as a backdrop to it. Its ingredients are a predictable daily structure, rules that every member of staff applies consistently, and shared responsibility through community meetings so that clients practise the social skills they will need outside. Separating clients from one another or making unit decisions without them removes the very interactions that make the milieu therapeutic.',
 '{"options":[{"id":"A","text":"The physical and social environment of the unit is itself used as a treatment"},{"id":"B","text":"Unit rules are clear and every member of staff applies them the same way"},{"id":"C","text":"Clients attend community meetings and share responsibility for how the unit runs"},{"id":"D","text":"Clients are kept apart from one another so that conflict cannot arise"},{"id":"E","text":"There is a structured daily routine of predictable activities"},{"id":"F","text":"Decisions about the unit are made by the consultant alone and then announced to clients"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Using the environment deliberately as a therapeutic agent is the defining idea of milieu therapy.","B":"Correct. Consistent limits applied by every member of staff are what make the environment predictable and safe.","C":"Correct. Community meetings give clients a share in the running of the unit and a place to practise social skills.","D":"Incorrect. Keeping clients apart removes the peer interaction that milieu therapy depends on.","E":"Correct. A predictable daily structure reduces anxiety and supports the return of normal functioning.","F":"Incorrect. Excluding clients from decisions removes the shared responsibility that defines a therapeutic milieu."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Mental Health', 'Psychiatric/Mental Health',
 'Milieu therapy', 'Features of a therapeutic environment', 'Medium', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550023', 'SATA',
 'The nurse observes a client in the day room shortly after a visitor has left. Which findings are early warning signs that the client may become aggressive? Select all that apply.',
 'Aggression very rarely occurs without warning, and recognising the prodromal signs is what makes early de-escalation possible. Motor restlessness, muscle tension, a rising voice and prolonged intense staring all indicate escalating arousal and are the point at which quiet, low-stimulus intervention still works. Waiting for a threat or a raised fist means intervening at the point where the least restrictive options have already been lost.',
 '{"options":[{"id":"A","text":"Pacing rapidly up and down the corridor"},{"id":"B","text":"Clenched fists and a rigid jaw"},{"id":"C","text":"Speaking faster and more loudly than usual"},{"id":"D","text":"Sitting quietly reading a newspaper"},{"id":"E","text":"Prolonged, intense staring at another client"},{"id":"F","text":"Accepting the offer of a cup of tea"},{"id":"G","text":"Asking the nurse what time visiting starts tomorrow"}]}'::jsonb,
 '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Motor restlessness such as rapid pacing is one of the earliest signs of rising arousal.","B":"Correct. Increased muscle tension in the hands and jaw signals that arousal is building towards action.","C":"Correct. A rising rate and volume of speech commonly precedes verbal and then physical aggression.","D":"Incorrect. Quiet, settled activity is not a warning sign of impending aggression.","E":"Correct. Prolonged, fixed staring at another person is a recognised precursor to assault.","F":"Incorrect. Accepting an ordinary offer indicates engagement rather than escalation.","G":"Incorrect. A routine question about visiting is normal social behaviour, not a warning sign."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Aggression', 'Warning signs of escalation', 'Easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550024', 'SATA',
 'A client is admitted to a mental health unit following an attempt to end his life. Which nursing actions promote environmental safety? Select all that apply.',
 'Environmental safety for a client at risk of suicide means removing means, removing anchor points and maintaining the prescribed level of observation without gaps. Searching belongings alongside the client preserves dignity while removing sharps, ligature material and stockpiled medication. Isolation at the end of a corridor, unchecked items brought in by visitors, and reliance on a signed agreement instead of observation all reduce protection rather than increase it.',
 '{"options":[{"id":"A","text":"Search belongings together with the client and remove sharps, belts, cords and medication"},{"id":"B","text":"Check that the bedroom contains no ligature anchor points such as exposed rails or hooks"},{"id":"C","text":"Maintain the prescribed level of observation at all times, including in the bathroom if that is specified"},{"id":"D","text":"Allocate the client a single room at the far end of the corridor so that he has privacy"},{"id":"E","text":"Ask the client to sign a no-harm agreement and then reduce the observation level"},{"id":"F","text":"Allow visitors to bring items in without checking them so that trust is not damaged"}]}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Removing means while involving the client maintains safety and preserves dignity.","B":"Correct. Removing ligature anchor points addresses the commonest method of inpatient suicide.","C":"Correct. Observation only protects if it is unbroken, including during periods of privacy where it is prescribed.","D":"Incorrect. An isolated room away from the nurse station reduces observation and increases risk.","E":"Incorrect. A no-harm agreement is not a safety intervention and must never be used to justify reducing observation.","F":"Incorrect. Unchecked items are a common route by which means of harm reach the unit."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Suicide risk', 'Environmental safety', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SATA_550025', 'SATA',
 'A client becomes physically aggressive towards staff and, after verbal de-escalation and offers of medication have failed, is placed in seclusion. Which nursing actions are required? Select all that apply.',
 'Seclusion and restraint are last resorts, used only when less restrictive alternatives have been tried and have failed, and both the attempt and the failure must be documented. Once in force, the client requires continuous observation, recorded physical and psychological assessment at set intervals, regular offers of fluid, toileting and comfort, and a prescription from an authorised prescriber within the required time. Seclusion ends at the earliest point the client is safe, never at a time chosen for the convenience of the unit.',
 '{"options":[{"id":"A","text":"Document which less restrictive measures were attempted and why they were ineffective"},{"id":"B","text":"Observe the client continuously and record physical and psychological status at set intervals"},{"id":"C","text":"Offer fluids, toileting and comfort measures at regular intervals"},{"id":"D","text":"Obtain a prescription for seclusion from the authorised prescriber within the required time"},{"id":"E","text":"Continue the seclusion until the end of the shift so that the unit remains settled"},{"id":"F","text":"Withhold any explanation until the client is calm enough to apologise"},{"id":"G","text":"Use seclusion as the first response whenever a client raises his voice on the unit"}]}'::jsonb,
 '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Evidence that less restrictive alternatives were tried and failed is a legal requirement for the intervention.","B":"Correct. Continuous observation with recorded assessment protects the client from physical harm during seclusion.","C":"Correct. Basic needs continue to be met throughout; seclusion does not suspend the duty of care.","D":"Correct. Seclusion requires authorisation by a prescriber within the timeframe set by policy.","E":"Incorrect. Seclusion ends as soon as the client is safe; continuing it for unit convenience is punitive and unlawful.","F":"Incorrect. Requiring an apology makes the intervention a punishment; explanation and debriefing are part of care.","G":"Incorrect. Seclusion is a last resort, never a first response to raised voices or minor disturbance."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Seclusion and restraint', 'Least restrictive alternative', 'Hard', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_550026', 'SELECT_N',
 'A client on a mental health unit tells the nurse that he can hear two voices arguing about him and that they are getting louder. Which 3 nurse responses are appropriate?',
 'The nurse neither agrees that the voices are real nor argues that they are imaginary. The recommended pattern is to state honestly that the nurse does not hear them, acknowledge that they are real and frightening to the client, ask what they are saying so risk can be judged, and offer presence while they are at their worst. Pretending to interact with the voices validates them, and telling the client to ignore them dismisses an experience he cannot control.',
 '{"options":[{"id":"A","text":"I do not hear any voices, but I can see that they are frightening you."},{"id":"B","text":"What are the voices saying to you?"},{"id":"C","text":"You are safe here. I will stay with you while they are loud."},{"id":"D","text":"The voices are only in your imagination."},{"id":"E","text":"Ask the voices to tell me what it is they want."},{"id":"F","text":"Try to ignore them and they will go away on their own."}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. It is honest about the nurse experience while accepting that the distress is real.","B":"Correct. Establishing the content is essential to judging risk, particularly for commands to harm.","C":"Correct. Offering presence and reassurance of safety reduces fear without validating the hallucination.","D":"Incorrect. Dismissing the experience as imaginary is not reassuring and damages trust.","E":"Incorrect. Speaking to the voices as if they were people validates the hallucination as real.","F":"Incorrect. A client experiencing loud hallucinations cannot simply ignore them, and the advice sounds dismissive."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Hallucinations', 'Responding to a client who is hallucinating', 'Medium', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_550027', 'SELECT_N',
 'During an assessment in the community, a client discloses that he has been thinking about ending his life. Which 3 questions best assess the lethality of the plan?',
 'Lethality is assessed by asking about method, means and specificity: how the client would do it, whether he already has what he needs, and whether a time and place have been chosen. Directness does not plant the idea; it is the only way to establish how close the client is to acting. Appeals to family, exploration of origins and requests for promises may all have a place in care but tell the nurse nothing about how dangerous the current plan is.',
 '{"options":[{"id":"A","text":"Have you decided how you would do it?"},{"id":"B","text":"Do you already have what you would need to carry it out?"},{"id":"C","text":"Have you thought about when and where you would do it?"},{"id":"D","text":"Do you not think your children would be devastated?"},{"id":"E","text":"What made you start feeling this way in the first place?"},{"id":"F","text":"Will you promise me that you will not do anything tonight?"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. The method chosen is a direct measure of lethality and of how far planning has progressed.","B":"Correct. Access to the means is the strongest single predictor of whether a plan can be acted on.","C":"Correct. A specific time and place indicate a plan that is close to being carried out.","D":"Incorrect. Appealing to guilt about family increases shame and gives no information about lethality.","E":"Incorrect. Understanding the origins matters for longer-term care but does not measure current danger.","F":"Incorrect. Extracting a promise is not an assessment and offers no protection in itself."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Suicide risk', 'Lethality assessment', 'Medium', 'CURATOR_LABEL', 'Apply', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_SELN_550028', 'SELECT_N',
 'A nurse is beginning a therapeutic relationship with a newly admitted client on a mental health unit. Which 3 tasks belong to the orientation phase?',
 'The orientation phase establishes the frame of the relationship: roles are clarified, trust is begun, the purpose, frequency and expected length of contact are agreed, and the limits of confidentiality are explained so that the client knows in advance what must be shared with the team. Problem work and the testing of new coping strategies belong to the working phase, and reviewing progress and preparing for the ending belong to termination, although termination is first mentioned in orientation. Exchanging personal contact details is a boundary violation in every phase.',
 '{"options":[{"id":"A","text":"Agreeing the purpose, frequency and expected length of the meetings"},{"id":"B","text":"Explaining the limits of confidentiality"},{"id":"C","text":"Building initial trust and clarifying the role of the nurse"},{"id":"D","text":"Working through the problems the client has identified and testing new coping skills"},{"id":"E","text":"Reviewing progress made and preparing the client for the ending of the relationship"},{"id":"F","text":"Exchanging personal telephone numbers so the client can make contact after discharge"}],"select_count":3}'::jsonb,
 '{"answers":["A","B","C"],"feedback":{"A":"Correct. Agreeing the contract for the relationship is a defining task of the orientation phase.","B":"Correct. The client must know from the outset what will be shared with the team and why.","C":"Correct. Establishing trust and clarifying roles is the central work of orientation.","D":"Incorrect. Active problem work and skills practice belong to the working phase.","E":"Incorrect. Reviewing gains and preparing for the ending belong to the termination phase.","F":"Incorrect. Sharing personal contact details is a boundary violation regardless of phase."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Nurse-client relationship', 'Orientation phase', 'Medium', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_550029', 'MATRIX',
 'The nurse is documenting the perceptual disturbances reported by clients on a mental health unit. For each client report, select the modality of hallucination it describes.',
 'Hallucinations are classified by the sense involved, and the order of frequency in psychiatric illness is auditory, then visual, then tactile, gustatory and olfactory. Auditory hallucinations predominate in schizophrenia, whereas visual and tactile hallucinations should always prompt the nurse to consider a physical cause such as delirium or substance withdrawal. Accurate classification therefore guides not only documentation but the search for a medical explanation.',
 '{"rows":[{"id":"r1","text":"Hears a voice that comments on everything he does, although he is alone in the room"},{"id":"r2","text":"Sees a small child standing at the end of the bed when no one is there"},{"id":"r3","text":"Reports insects crawling about beneath the skin of the forearms"},{"id":"r4","text":"Says that all food and even plain water taste of metal and rot"},{"id":"r5","text":"Describes a smell of burning flesh in the room that nobody else can detect"}],"columns":[{"id":"c1","text":"Auditory"},{"id":"c2","text":"Visual"},{"id":"c3","text":"Tactile"},{"id":"c4","text":"Gustatory"},{"id":"c5","text":"Olfactory"}],"row_label":"Client report"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c4","r5":"c5"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Hallucinations', 'Modalities', 'Medium', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MAT_550030', 'MATRIX',
 'A nurse is teaching student nurses about schizophrenia. For each finding, select whether it is a positive symptom or a negative symptom.',
 'Positive symptoms are experiences added to normal functioning, such as hallucinations, delusions and disorganised speech, and they generally respond well to antipsychotic medication. Negative symptoms are losses from normal functioning, such as blunted affect, poverty of speech, avolition and social withdrawal, and they respond far less well to medication and improve slowly with structure and rehabilitation. The distinction matters clinically because negative symptoms are routinely misread by families and staff as laziness or depression.',
 '{"rows":[{"id":"r1","text":"Hears voices that other people do not hear"},{"id":"r2","text":"Flat, unchanging facial expression whatever the topic"},{"id":"r3","text":"Speech shifts between unrelated topics with no traceable link"},{"id":"r4","text":"Answers questions in one or two words and offers nothing further"},{"id":"r5","text":"Believes the neighbours are broadcasting his thoughts to the street"},{"id":"r6","text":"Has lost the drive to wash or dress without prompting"}],"columns":[{"id":"c1","text":"Positive symptom"},{"id":"c2","text":"Negative symptom"}],"row_label":"Finding"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1","r6":"c2"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Schizophrenia', 'Positive versus negative symptoms', 'Easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MAT_550031', 'MATRIX',
 'A ward manager is reviewing situations that arose on a mental health unit during clinical supervision. For each situation, select the term that best describes it.',
 'Transference is the client unconsciously transferring feelings about a significant person from the past on to the nurse, while countertransference is the nurse doing the same towards the client. Both are normal, and both become a problem only when they are unrecognised and allowed to shape care. Inappropriate self-disclosure moves the focus from client to nurse, and a boundary violation is any action that turns the professional relationship into a personal one, of which secrecy from the team is the most reliable warning sign.',
 '{"rows":[{"id":"r1","text":"A client becomes angry with the nurse and calls her by the name of the older sister who he says always controlled him"},{"id":"r2","text":"The nurse finds herself avoiding a client who reminds her strongly of her own critical father"},{"id":"r3","text":"The nurse tells a bereaved client that she lost a parent last year and describes her own funeral arrangements in detail"},{"id":"r4","text":"The nurse buys a client cigarettes with her own money each week and asks the team not to mention it"},{"id":"r5","text":"A client insists on being seen only by one nurse, saying she is the only one who understands him, just as his mother did"}],"columns":[{"id":"c1","text":"Transference"},{"id":"c2","text":"Countertransference"},{"id":"c3","text":"Inappropriate self-disclosure"},{"id":"c4","text":"Boundary violation"}],"row_label":"Situation"}'::jsonb,
 '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c4","r5":"c1"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Nurse-client relationship', 'Transference and countertransference', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MMR_550032', 'MATRIX_MR',
 'A nurse is assessing an older client whose family report a change in thinking and behaviour. For each feature, select every condition it is consistent with. Each feature has at least one condition.',
 'Delirium, dementia and depression overlap enough in older clients that they are regularly mistaken for one another, and the discriminators are onset, course, attention and reversibility. Delirium begins over hours to days with fluctuating attention and is reversible when the cause is treated; dementia begins insidiously over years and is progressive; depression may present with poor concentration, apathy and a client who gives up quickly on testing, and it is also reversible with treatment. Because more than one can be present at once, features that fit several conditions must be interpreted alongside the history rather than in isolation.',
 '{"rows":[{"id":"r1","text":"Onset over a period of hours to days"},{"id":"r2","text":"Attention that is impaired and fluctuates through the day"},{"id":"r3","text":"Insidious onset over months to years"},{"id":"r4","text":"The client answers I do not know to memory questions and gives up quickly"},{"id":"r5","text":"Low mood, early morning waking and loss of appetite"},{"id":"r6","text":"Potentially fully reversible once the underlying problem is treated"},{"id":"r7","text":"Reduced interest in activities the client previously enjoyed"}],"columns":[{"id":"c1","text":"Delirium"},{"id":"c2","text":"Dementia"},{"id":"c3","text":"Depression"}],"row_label":"Feature"}'::jsonb,
 '{"cells":{"r1":["c1"],"r2":["c1"],"r3":["c2"],"r4":["c3"],"r5":["c3"],"r6":["c1","c3"],"r7":["c2","c3"]},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Delirium versus dementia versus depression', 'Feature attribution', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_MMR_550033', 'MATRIX_MR',
 'The nurse is handing over observations made on an acute mental health unit. For each observation, select every category that applies. Each observation has at least one category.',
 'Risk assessment separates risk of harm to self from risk of harm to others, and then asks whether the situation requires action now or can be managed within the existing care plan. Concealed means, a command hallucination the client may obey, giving away possessions and a specific threat against a named person all demand immediate action. Passive thoughts of life not being worth living, with no plan and an agreement to tell staff, remain a risk to self that is managed through the existing plan rather than an emergency.',
 '{"rows":[{"id":"r1","text":"A client is found to have hidden a razor blade inside the mattress"},{"id":"r2","text":"A client is shouting threats at another client and blocking the corridor"},{"id":"r3","text":"A client reports a voice telling him to jump from a window and says he may obey it"},{"id":"r4","text":"A client has given away his possessions and written letters to his family"},{"id":"r5","text":"A client states that he will find the man who gave evidence against him as soon as he is discharged"},{"id":"r6","text":"A client says that he sometimes feels life is not worth living, has no plan, and has agreed to tell staff if that changes"}],"columns":[{"id":"c1","text":"Risk of harm to self"},{"id":"c2","text":"Risk of harm to others"},{"id":"c3","text":"Requires immediate nursing action"}],"row_label":"Observation"}'::jsonb,
 '{"cells":{"r1":["c1","c3"],"r2":["c2","c3"],"r3":["c1","c3"],"r4":["c1","c3"],"r5":["c2","c3"],"r6":["c1"]},"feedback":{}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Risk assessment', 'Risk to self and risk to others', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_CLZ_550034', 'CLOZE',
 'During a night shift a client points to a curtain moving in the draught and says that a person is hiding behind it. When the nurse draws the curtain back and switches on the light, the client agrees that it is only the curtain. This experience is an example of {1}, and the most appropriate nursing action is to {2}.',
 'The defining feature of an illusion is that the referent is real: a genuine stimulus has been misinterpreted, and the perception corrects itself once the stimulus is clarified. That is why the intervention targets the environment rather than the belief. Contradiction, exploration of content and sedation all belong to other categories of altered perception and leave the misread stimulus in place.',
 '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"a delusion"},{"id":"c2","text":"a hallucination"},{"id":"c3","text":"an illusion"},{"id":"c4","text":"confabulation"}]},{"id":"b2","choices":[{"id":"c1","text":"alter the lighting so the object is clearly seen and name it together with the client"},{"id":"c2","text":"tell the client firmly that nobody is there and leave the light switched off"},{"id":"c3","text":"explore in detail who the client believes is hiding behind the curtain"},{"id":"c4","text":"give the prescribed as-required sedative straight away"}]}]}'::jsonb,
 '{"answers":{"b1":"c3","b2":"c1"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Altered perception', 'Recognising and managing an illusion', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),

('NCLEX_TF_550035', 'TF',
 'A no-harm agreement signed by a client who is at risk of suicide removes the need to maintain the prescribed level of observation. Is this statement true or false?',
 'A no-harm or safety agreement can open a conversation and may help a client articulate what he will do when distress rises, but there is no evidence that it prevents suicide. It has no legal standing, it cannot be relied on by a client whose intent changes, and it may give staff false confidence. Observation, removal of means and continuing assessment remain the interventions that actually protect the client.',
 '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb,
 '{"answer":"B","feedback":{"A":"Incorrect. A signed agreement has no protective effect and must never be used to justify reducing observation.","B":"Correct. No-harm agreements are unproven, carry no legal weight, and do not replace observation, removal of means or ongoing assessment."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Suicide risk', 'No-harm agreements', 'Very easy', 'CURATOR_LABEL', 'Understand', '{}',
 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');
